css:
:root{--navy:#073d78;--navy-dark:#052f5e;--blue:#1267bd;--red:#d7192e;--pale:#eef7fd;--line:#dce9f4;--muted:#5f7387;
--bs-body-font-family:"DM Sans",Arial,sans-serif;--bs-body-color:#173c63;--bs-link-hover-color:var(--navy);
--shadow:0 14px 40px rgba(7,61,120,.10);--radius:20px;--header-h:80px}
html{scroll-behavior:smooth;scroll-padding-top:var(--header-h)}
@media(min-width:1920px){html{font-size:18px}}
@media(min-width:2560px){html{font-size:24px}}
@media(min-width:3200px){html{font-size:28px}}
body{overflow-x:hidden}
a,a:hover,a:focus{text-decoration:none}
h1,h2,h3,h4{font-family:Manrope,sans-serif;color:var(--navy);letter-spacing:-.02em}
.wrap{width:100%;max-width:1320px;margin-inline:auto;padding-inline:1.25rem}
@media(min-width:1920px){.wrap{max-width:1560px}}
@media(min-width:2560px){.wrap{max-width:1900px}}
@media(min-width:3200px){.wrap{max-width:2200px}}
:focus-visible{outline:3px solid rgba(18,103,189,.45);outline-offset:2px}
.btn-arsh{--bs-btn-bg:var(--red);--bs-btn-border-color:var(--red);--bs-btn-color:#fff;--bs-btn-hover-bg:#b9132a;--bs-btn-hover-border-color:#b9132a;--bs-btn-hover-color:#fff;--bs-btn-active-bg:#a31024;--bs-btn-active-border-color:#a31024;--bs-btn-active-color:#fff;font-weight:600;border-radius:10px;padding:.65rem 1.2rem;font-size:.92rem;box-shadow:0 8px 18px rgba(215,25,46,.2)}
.btn-ghost{--bs-btn-bg:#fff;--bs-btn-color:var(--blue);--bs-btn-border-color:#cfe2f3;--bs-btn-hover-bg:var(--pale);--bs-btn-hover-color:var(--navy);--bs-btn-hover-border-color:#b6d3ec;font-weight:600;border-radius:10px;padding:.65rem 1.2rem;font-size:.92rem}

/* Header */
.topbar{background:var(--navy-dark);color:#cfe1f2;font-size:.78rem}
.topbar a{color:#fff;font-weight:600}
.site-header{position:sticky;top:0;z-index:1030;background:rgba(255,255,255,.92);backdrop-filter:blur(14px);border-bottom:1px solid #e5edf4;height:var(--header-h)}
.site-header .wrap{height:100%;display:flex;align-items:center;gap:1rem}
.logo img{height:46px;width:auto;display:block}
.main-nav{display:flex;align-items:center;gap:.25rem;margin-left:auto}
.main-nav a{padding:.5rem .85rem;border-radius:10px;font-size:.88rem;font-weight:600;color:#244665;transition:background .2s,color .2s}
.main-nav a:hover,.main-nav a.active{background:var(--pale);color:var(--blue)}
.menu-btn{width:44px;height:44px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--navy);font-size:1.5rem;display:none;align-items:center;justify-content:center;padding:0}
.search-btn{width:42px;height:42px;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--navy);font-size:1rem;display:flex;align-items:center;justify-content:center;padding:0;flex:none;transition:.2s}
.search-btn:hover{background:var(--pale);color:var(--blue)}
.sm{position:fixed;inset:0;z-index:1070;display:none;align-items:flex-start;justify-content:center;padding:12vh 1rem 1rem;background:rgba(5,30,60,.6);backdrop-filter:blur(4px)}
.sm.open{display:flex}
.sm-box{width:min(640px,100%);background:#fff;border-radius:20px;padding:1.25rem;box-shadow:0 30px 70px rgba(5,30,60,.35)}
.sm-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:.9rem}
.sm-head h2{font-size:1.05rem;font-weight:700;margin:0}
.sm-close{width:36px;height:36px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);display:flex;align-items:center;justify-content:center;padding:0}
.sm-box .input-group-text{height:3rem;background:#f8fbfe;border:1px solid #d3e3f1;border-right:0;border-radius:12px 0 0 12px;color:var(--blue)}
.sm-box .form-control{height:3rem;border:1px solid #d3e3f1;border-left:0;border-right:0;border-radius:0;background:#f8fbfe;font-size:.95rem}
.sm-box .btn{height:3rem;border-radius:0 12px 12px 0;box-shadow:none}
.sm-chips{display:flex;flex-wrap:wrap;gap:.45rem;margin-top:.9rem}
.sm-chips button{border:1px solid var(--line);background:#fff;color:var(--blue);border-radius:999px;padding:.3rem .8rem;font-size:.8rem;font-weight:500}
.sm-chips button:hover{background:var(--pale)}
.scrim{position:fixed;inset:0;background:rgba(5,30,60,.55);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.3s;z-index:1040}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(86vw,360px);background:#fff;z-index:1050;transform:translateX(100%);transition:transform .35s cubic-bezier(.22,.8,.3,1);display:flex;flex-direction:column;box-shadow:-20px 0 50px rgba(7,61,120,.2)}
.drawer-open .scrim{opacity:1;visibility:visible}
.drawer-open .drawer{transform:none}
.drawer-open{overflow:hidden}
.drawer-top{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--line)}
.drawer-top img{height:40px}
.drawer-close{width:40px;height:40px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);font-size:1.1rem;padding:0;display:flex;align-items:center;justify-content:center}
.drawer-links{flex:1;overflow-y:auto;padding:.75rem 1rem}
.drawer-links a{display:flex;align-items:center;gap:.9rem;padding:.8rem .7rem;border-radius:14px;font-weight:600;font-size:.95rem;color:var(--navy)}
.drawer-links a i{width:38px;height:38px;border-radius:12px;background:var(--pale);color:var(--blue);display:grid;place-items:center;font-size:1.05rem}
.drawer-links a:hover{background:var(--pale)}
.drawer-links a::after{content:"\F285";font-family:"bootstrap-icons";margin-left:auto;color:#9bb3c9;font-size:.8rem}
.drawer-foot{padding:1.1rem 1.25rem 1.5rem;border-top:1px solid var(--line);background:var(--pale)}
.drawer-emerg{display:flex;align-items:center;gap:.75rem;margin-bottom:.9rem;color:var(--navy);font-weight:700}
.drawer-emerg i{width:40px;height:40px;border-radius:50%;background:var(--red);color:#fff;display:grid;place-items:center}
.drawer-emerg small{display:block;font-weight:500;color:var(--muted)}
@media(max-width:991.98px){.main-nav,.header-cta{display:none}.menu-btn{display:flex}.search-btn{margin-left:auto}:root{--header-h:66px}}

/* Page banner */
.page-hero{background:radial-gradient(circle at 15% 20%,#fff 0,var(--pale) 55%,#e3f1fb 100%);padding:1rem 0 clamp(1.6rem,3vw,2.4rem)}
.crumb{display:flex;gap:.45rem;align-items:center;font-size:.76rem;color:var(--muted);margin-bottom:.5rem}
.crumb a{color:var(--blue);font-weight:600}
.page-hero h1{font-size:clamp(1.6rem,2.8vw,2.4rem);font-weight:800;margin:0 0 .35rem}
.page-hero p{color:#49647d;max-width:42rem;margin:0;font-size:.92rem}


/* Doctors layout */
.section{padding:clamp(1.2rem,2.5vw,2rem) 0 clamp(2.6rem,5vw,4.5rem)}
.fbox{background:#fff;border:1px solid var(--line);border-radius:22px;padding:1.2rem;box-shadow:var(--shadow)}
@media(min-width:992px){.fbox{position:sticky;top:calc(var(--header-h) + 1rem)}}
.fhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem}
.fhead h2{font-size:1.1rem;font-weight:700;margin:0}
.fhead button{border:0;background:none;color:var(--blue);font-weight:600;font-size:.88rem;padding:0}
.fbox .form-label{font-size:.82rem;font-weight:600;color:var(--navy);margin-bottom:.3rem}
.fbox .form-label small{color:#d99a1b;font-weight:600}
.fbox .form-select,.fbox .form-control{height:2.8rem;border-radius:12px;border:1px solid #cfe2f3;background-color:#f8fbfe;font-size:.88rem;color:#2c4a68}
.fbox .form-control:focus,.fbox .form-select:focus{box-shadow:0 0 0 3px rgba(18,103,189,.14);border-color:#8fbce6}
.fbox .input-group-text{height:2.8rem;border:1px solid #cfe2f3;border-right:0;background:#f8fbfe;border-radius:12px 0 0 12px;color:var(--blue)}
.fbox .input-group .form-control{border-left:0;border-radius:0 12px 12px 0}
.fbox .btn-arsh{height:2.9rem;width:100%;border-radius:12px;margin-top:.4rem}
.tries{display:flex;flex-wrap:wrap;gap:.4rem;margin-top:1rem;padding-top:1rem;border-top:1px solid #edf3f8}
.tries span{font-size:.76rem;color:var(--muted);width:100%}
.tries button{border:1px solid var(--line);background:#fff;color:var(--blue);border-radius:999px;padding:.25rem .7rem;font-size:.76rem;font-weight:500}
.tries button:hover{background:var(--pale)}
.ftoggle{display:none;width:100%;margin-bottom:1rem;align-items:center;justify-content:space-between;background:#fff;border:1px solid var(--line);border-radius:14px;padding:.75rem 1rem;font-weight:600;color:var(--navy);box-shadow:0 6px 18px rgba(7,61,120,.06)}
.ftoggle i::before{vertical-align:-.1em}
@media(max-width:991.98px){.ftoggle{display:flex}.fcol{display:none;margin-bottom:1rem}.fcol.open{display:block}}
.count{font-size:.86rem;color:var(--muted);margin-bottom:.8rem}
.count b{color:var(--navy)}

/* Doctor card (horizontal) */
.dcard{display:grid;grid-template-columns:230px 1fr;background:#fff;border:1.5px solid #bfdff0;border-radius:20px;overflow:hidden;box-shadow:0 6px 22px rgba(7,61,120,.06);transition:box-shadow .25s,transform .25s}
.dcard:hover{box-shadow:var(--shadow);transform:translateY(-2px)}
.dph{position:relative;background:linear-gradient(180deg,#eaf4fc,#f7fbff);min-height:230px}
.dph img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top}
.dph .bar{position:absolute;left:0;right:0;bottom:0;background:var(--navy);color:#fff;font-size:.74rem;font-weight:600;text-align:center;padding:.4rem .5rem}
.dbody{padding:1.15rem 1.4rem 1.2rem;display:flex;flex-direction:column}
.dbody h3{font-size:1.2rem;font-weight:700;margin:0 0 .3rem;text-transform:uppercase;letter-spacing:0}
.dsub{font-weight:600;font-size:.92rem;color:#244665;margin-bottom:.6rem}
.dq{font-size:.82rem;color:var(--muted);line-height:1.6}
.dq b{color:var(--blue);font-weight:700;font-size:.74rem;letter-spacing:.3px;text-transform:uppercase;margin-right:.25rem}
.dmeta{display:flex;flex-wrap:wrap;gap:.3rem 1.2rem;font-size:.8rem;color:var(--muted);margin-top:.55rem}
.dmeta i{color:var(--blue);margin-right:.3rem}
.dact{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:auto;padding-top:1rem}
.dact .btn{padding:.5rem 1.05rem;font-size:.84rem;border-radius:10px;box-shadow:none}
@media(max-width:575.98px){
 .dcard{grid-template-columns:clamp(92px,28vw,108px) 1fr;border-radius:16px}
 .dph{min-height:0}
 .dph .bar{font-size:.62rem;padding:.3rem .2rem}
 .dbody{padding:.8rem .7rem .9rem}
 .dbody h3{font-size:.9rem}
 .dsub{font-size:.76rem;margin-bottom:.35rem}
 .dq{font-size:.7rem}
 .dmeta{font-size:.7rem;margin-top:.35rem}
 .dact{gap:.35rem;padding-top:.7rem;flex-wrap:nowrap}
 .dact .btn{flex:1 1 0;min-width:0;white-space:nowrap;text-align:center;padding:.45rem .2rem;font-size:clamp(.58rem,2.7vw,.7rem);border-radius:8px}
}
.in{animation:dIn .45s both}
@keyframes dIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.in{animation:none}}
.loader{display:none;justify-content:center;padding:2rem 0 0}
.loader.on{display:flex}
.loader .spinner-border{color:var(--blue);width:2rem;height:2rem;border-width:.25em}
.end-note{display:none;text-align:center;color:var(--muted);font-size:.85rem;padding-top:1.6rem}
.empty{display:none;text-align:center;padding:3rem 1rem;border:1px dashed #b9d3ea;border-radius:var(--radius);background:#f8fbfe}
.empty i{font-size:2.2rem;color:var(--blue)}
.empty h3{font-size:1.15rem;margin:.6rem 0 .3rem}
.empty p{color:var(--muted);margin:0 0 1rem;font-size:.9rem}

/* Emergency strip (same as homepage) */
.strip{background:linear-gradient(110deg,var(--navy-dark),var(--navy));color:#fff;padding:.9rem 0}
.strip .wrap{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}
.strip .lft{display:flex;align-items:center;gap:.9rem}
.strip-ic{width:38px;height:38px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;flex:none;box-shadow:0 0 0 6px rgba(215,25,46,.22)}
.strip b{font-family:Manrope;font-weight:700;font-size:1rem}
.strip small{display:block;color:#b9d0e6;font-size:.78rem}
.call{background:var(--red);color:#fff;border-radius:999px;padding:.4rem 1rem;font-size:.85rem;font-weight:600}
.call:hover{color:#fff;background:#b9132a}

/* Footer */
footer{background:#041f3f;color:#9fb8ce;padding:2.2rem 0 1rem;font-size:.8rem;border-top:3px solid var(--red)}
footer h6{color:#e6f0f9;font-weight:600;font-size:.82rem;margin-bottom:.8rem}
footer a{color:#9fb8ce;display:block;margin-bottom:.4rem}
footer a:hover{color:#fff}
footer p{margin:0 0 .8rem;max-width:26rem;line-height:1.55}
footer .fl a{transition:color .2s,padding-left .2s}
footer .fl a:hover{padding-left:.25rem}
.social{display:flex;gap:.5rem}
.social a{width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;margin:0;color:#cfe1f2}
.social a:hover{background:var(--red)}
.fi{display:flex;gap:.55rem;margin-bottom:.45rem;color:#9fb8ce}
.copy{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem;border-top:1px solid rgba(255,255,255,.08);margin-top:1.5rem;padding-top:1rem;font-size:.74rem;color:#7f9bb3}
.copy a{display:inline;margin:0;color:#cfe1f2;font-weight:600}
.copy a:hover{color:#fff}

/* Icon centering */
.cx-btn .bi,.drawer-close .bi,.menu-btn .bi,.search-btn .bi,.sm-close .bi,.drawer-links a>i,.drawer-emerg .bi,.social .bi{display:flex;align-items:center;justify-content:center;line-height:1}
.cx-btn .bi::before,.drawer-close .bi::before,.menu-btn .bi::before,.search-btn .bi::before,.sm-close .bi::before,.drawer-links a>i::before,.drawer-emerg .bi::before,.social .bi::before{display:block;vertical-align:0;line-height:1}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

/* Mega menu */
.mega-trigger{border:0;background:none;display:flex;align-items:center;gap:.3rem;padding:.5rem .85rem;border-radius:10px;font-size:.88rem;font-weight:600;color:#244665;font-family:inherit;transition:background .2s,color .2s}
.mega-trigger i{font-size:.7rem;transition:transform .25s}
.mega-trigger:hover,.mega-trigger.on{background:var(--pale);color:var(--blue)}
.mega-trigger.on i{transform:rotate(180deg)}
.mega{position:absolute;left:0;right:0;top:100%;background:#fff;border-top:1px solid var(--line);box-shadow:0 34px 60px rgba(7,61,120,.18);opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .22s,transform .22s,visibility .22s;max-height:calc(100vh - var(--header-h) - 12px);overflow-y:auto}
.mega.open{opacity:1;visibility:visible;transform:none}
.mega-in{display:grid;grid-template-columns:16rem 1fr;gap:1.6rem;padding-block:1.5rem}
.mega-side{background:linear-gradient(150deg,var(--navy),#0d5aa8);color:#fff;border-radius:20px;padding:1.4rem;display:flex;flex-direction:column;align-items:flex-start}
.mega-count{background:rgba(255,255,255,.14);border-radius:999px;padding:.2rem .7rem;font-size:.74rem;font-weight:600;margin-bottom:.8rem}
.mega-side h3{color:#fff;font-size:1.35rem;font-weight:800;margin:0 0 .4rem}
.mega-side p{font-size:.85rem;color:#cfe1f2;margin:0 0 1.1rem}
.mega-side .btn{font-size:.84rem;padding:.55rem 1rem;box-shadow:none}
.mega-link{margin-top:.8rem;color:#fff;font-weight:600;font-size:.85rem}
.mega-link:hover{color:#fff;opacity:.85}
.mgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:.15rem .5rem;align-content:start}
@media(min-width:1200px){.mgrid{grid-template-columns:repeat(4,1fr)}}
.mi{display:flex;gap:.7rem;align-items:center;padding:.55rem .6rem;border-radius:14px;transition:background .2s}
.mi:hover{background:var(--pale)}
.mi-ic{width:40px;height:40px;border-radius:12px;background:var(--pale);color:var(--blue);display:flex;align-items:center;justify-content:center;flex:none;font-size:1.1rem;transition:.2s}
.mi-ic i{display:flex;align-items:center;justify-content:center;line-height:1}
.mi-ic i::before{display:block;vertical-align:0;line-height:1}
.mi:hover .mi-ic{background:var(--blue);color:#fff}
.mi b{display:block;font-size:.86rem;font-weight:600;color:var(--navy);line-height:1.25}
.mi small{display:block;font-size:.72rem;color:var(--muted);line-height:1.3;margin-top:.1rem}
@media(max-width:991.98px){.mega{display:none}}
@media(prefers-reduced-motion:reduce){.mega{transition:none}}
/* Drawer accordion */
.dacc{width:100%;display:flex;align-items:center;gap:.9rem;padding:.8rem .7rem;border:0;background:none;border-radius:14px;font-weight:600;font-size:.95rem;color:var(--navy);text-align:left;font-family:inherit}
.dacc:hover{background:var(--pale)}
.dacc>i{width:38px;height:38px;border-radius:12px;background:var(--pale);color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:1.05rem}
.dacc>i::before{display:block;vertical-align:0;line-height:1}
.dacc::after{content:"\F282";font-family:"bootstrap-icons";margin-left:auto;color:#9bb3c9;font-size:.8rem;transition:transform .25s}
.dacc[aria-expanded="true"]::after{transform:rotate(180deg)}
.dacc[aria-expanded="true"]{background:var(--pale)}
.dsub{display:grid;grid-template-rows:0fr;transition:grid-template-rows .3s ease}
.dsub.open{grid-template-rows:1fr}
.dsub>div{overflow:hidden;padding-left:1.1rem}
.drawer-links .dsub a{padding:.55rem .7rem;font-size:.88rem;font-weight:500;gap:.7rem;border-radius:10px}
.drawer-links .dsub a::after{display:none}
.drawer-links .dsub a i{width:30px;height:30px;border-radius:9px;font-size:.9rem}
.drawer-links .dsub a.dall{color:var(--blue);font-weight:600;padding-left:.7rem}
@media(prefers-reduced-motion:reduce){.dsub{transition:none}}

/* Doctors banner with background image */
.page-hero{position:relative;overflow:hidden;color:#fff;padding:clamp(1.7rem,3.4vw,2.8rem) 0;background:linear-gradient(100deg,rgba(5,47,94,.96) 0%,rgba(7,61,120,.88) 45%,rgba(7,61,120,.42) 100%),url("https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?auto=format&fit=crop&w=1920&q=80") center/cover no-repeat}
.page-hero::after{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;background:linear-gradient(90deg,var(--red),#ff6b78 40%,transparent)}
.page-hero .wrap{position:relative;z-index:1}
.hero-eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-size:.76rem;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#cfe1f2;margin-bottom:.6rem}
.hero-eyebrow i{width:8px;height:8px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px rgba(215,25,46,.3)}
.page-hero h1{color:#fff;font-size:clamp(1.9rem,3.6vw,3rem);font-weight:800;margin:0 0 .4rem}
.page-hero p{color:#d6e6f5;max-width:40rem;margin:0;font-size:clamp(.88rem,1.1vw,1rem)}
.hero-chips{display:flex;flex-wrap:wrap;gap:.55rem;margin-top:1.1rem}
.hero-chips span{display:inline-flex;align-items:center;gap:.45rem;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.24);backdrop-filter:blur(6px);border-radius:999px;padding:.35rem .85rem;font-size:.8rem;font-weight:600;color:#fff}
.hero-chips i{color:#ff8f9b;display:flex}
.hero-chips i::before{display:block;vertical-align:0;line-height:1}
@media(max-width:575.98px){.hero-chips{gap:.4rem;margin-top:.9rem}.hero-chips span{font-size:.7rem;padding:.3rem .65rem}}

/* Keep emergency access consistent with the homepage header. */
.site-header .wrap{gap:.7rem}
.main-nav a{padding-inline:.65rem}
.header-emergency{display:flex;align-items:center;gap:.55rem;padding:.42rem .72rem;border:1px solid #f2c9ce;border-radius:12px;background:#fff8f8;color:var(--red);font-size:.76rem;font-weight:700;line-height:1.15;white-space:nowrap}
.header-emergency>i{width:32px;height:32px;border-radius:10px;background:#ffe7e9;display:grid;place-items:center;font-size:.95rem}
.header-emergency small{display:block;color:#7c8997;font-size:.65rem;font-weight:600;margin-bottom:.1rem}
.header-emergency:hover{background:#fff0f1;color:#b9132a;border-color:#edabb3}
@media(max-width:1199.98px){.header-emergency{display:grid;place-items:center;width:42px;height:42px;padding:0;border:0;border-radius:12px;background:var(--red);color:#fff;flex:none}.header-emergency>i{width:auto;height:auto;background:transparent;color:#fff}.header-emergency span{display:none}}
